**Protocol Selection with Protocol Advisor:**

```
How Protocol Advisor Works:
1. Launch Protocol Advisor from VuGen
2. Specify application URL
3. Perform typical user actions
4. Advisor analyzes network traffic
5. Recommends best protocol(s)

Example Recommendation:
"Based on your application traffic, we recommend:
- Primary: Web - HTTP/HTML
- Secondary: Web Services
- Also detected: AJAX calls, consider TruClient"
```

**Recording Methods:**

| Method | How It Works | Best For |
|--------|--------------|----------|
| **Proxy Recording** | VuGen acts as proxy between browser and server | Most web applications |
| **Network-Level** | Captures packets at network level | Applications that can't use proxy |
| **Browser Extension** | Extension records browser events | AJAX-heavy applications |
| **Citrix ICA** | Captures screen and keyboard events | Citrix virtualized apps |
| **Cross-Platform** | Records on remote machines | Mobile, non-Windows apps |
| **Manual Coding** | Write scripts from scratch | APIs, experienced users |

**Script Structure:**

```c
// vuser_init.c - Runs once per Vuser at start
vuser_init()
{
    // Initialize connection, login, etc.
    web_url("home", "URL=https://example.com/", LAST);

    lr_output_message("vuser_init completed");
    return 0;
}

// Action.c - Runs repeatedly during test
Action()
{
    // Main business transactions

    // Start transaction for measurement
    lr_start_transaction("Search");

    web_submit_data("search",
        "Action=https://example.com/search",
        "Method=POST",
        ITEMDATA,
        "Name=query", "Value={searchTerm}", ENDITEM,
        LAST);

    // Check for expected content
    web_reg_find("Text=Results found", LAST);

    // End transaction
    lr_end_transaction("Search", LR_AUTO);

    // Think time between actions
    lr_think_time(5);

    return 0;
}

// vuser_end.c - Runs once at end
vuser_end()
{
    // Cleanup, logout
    web_url("logout", "URL=https://example.com/logout", LAST);

    lr_output_message("vuser_end completed");
    return 0;
}
```

**Parameterization in Depth:**

```c
// Parameter types available:
// File: Data from external files (CSV, TXT, Excel)
// Table: Data from database
// User-Defined: Manually entered values
// Random Number: Generated random numbers
// Unique Number: Guaranteed unique values
// Date/Time: Current date/time in various formats
// Vuser ID: Unique Vuser identifier
// Group Name: Vuser group name
// Iteration Number: Current iteration count

// Creating a parameter:
// 1. Select value to parameterize
// 2. Right-click → Replace with a parameter
// 3. Create new parameter "username"
// 4. Configure data source (users.dat)

// users.dat file:
// username,password
// john,pass123
// jane,secure456
// bob,test789

// Script with parameters:
web_submit_data("login",
    "Action=https://example.com/login",
    "Method=POST",
    ITEMDATA,
    "Name=username", "Value={username}", ENDITEM,
    "Name=password", "Value={password}", ENDITEM,
    LAST);

// Parameter functions:
lr_eval_string("{username}")  // Get parameter value
lr_save_string("newvalue", "newParam")  // Create runtime parameter
```

**Correlation in Depth:**

```c
// Automatic Correlation (Scan for Correlations)
// VuGen scans script and identifies dynamic values
// Creates web_reg_save_param statements automatically

// Manual Correlation:
// 1. Find dynamic value in response
// 2. Create correlation function before request that needs it

// Before correlation:
web_submit_data("login", ...);
web_url("dashboard", "URL=https://example.com/dashboard?session=ABC123", ...);
// session=ABC123 will be different next time

// After correlation:
web_submit_data("login", ...);

// Capture session ID from login response
web_reg_save_param("sessionId",
    "LB=session=",
    "RB=&",
    "Search=Body",
    LAST);

// Use captured value
web_url("dashboard", 
    "URL=https://example.com/dashboard?session={sessionId}", 
    LAST);

// Advanced correlation functions:
web_reg_save_param_ex(
    "ParamName=sessionId",
    "LB=session=",
    "RB=&",
    SEARCH_FILTERS,
    "Scope=Body",
    "IgnoreRedirections=Yes",
    LAST);

// Correlation functions for different content:
// web_reg_save_param_json - JSON responses
// web_reg_save_param_xpath - XML/HTML
// web_reg_save_param_regexp - Custom regex
```

**Transactions and Response Time Measurement:**

```c
// Basic transaction
lr_start_transaction("Login");
// Login actions
lr_end_transaction("Login", LR_AUTO);

// Nested transactions
lr_start_transaction("Checkout");
    lr_start_transaction("AddToCart");
    // Add to cart actions
    lr_end_transaction("AddToCart", LR_AUTO);

    lr_start_transaction("Payment");
    // Payment actions
    lr_end_transaction("Payment", LR_AUTO);
lr_end_transaction("Checkout", LR_AUTO);

// Transaction status
lr_end_transaction("Login", LR_PASS);   // Mark as passed
lr_end_transaction("Login", LR_FAIL);   // Mark as failed
lr_end_transaction("Login", LR_STOP);   // Stop transaction

// Transaction with custom response time
long start = clock();
// actions
long duration = clock() - start;
lr_end_transaction("Custom", LR_AUTO, duration);
```

**Checkpoints and Validation:**

```c
// Text checkpoint
web_reg_find("Text=Welcome, {username}", 
    "Fail=Found",  // Fail if found (negative testing)
    LAST);

// Image checkpoint
web_image_check("LogoCheck",
    "Src=logo.png",
    LAST);

// Advanced checkpoint with saving matched text
web_reg_save_param("price",
    "LB=<span class=\"price\">$",
    "RB=</span>",
    LAST);

// Manual checkpoint using if condition
if (atoi(lr_eval_string("{price}")) > 100) {
    lr_end_transaction("PriceCheck", LR_FAIL);
}
```

**VuGen Runtime Settings:**

| Setting Category | Key Options | Impact |
|-----------------|-------------|--------|
| **Think Time** | Ignore, Replay as recorded, Multiply by factor | Realism vs speed |
| **Logging** | Standard, Extended, Parameter substitution | Debug detail vs performance |
| **Browser Emulation** | Browser type, version, user agent | Accurate simulation |
| **Proxy** | No proxy, Manual, Use system | Network configuration |
| **HTTP Properties** | Keep-alive, chunked encoding, connection timeout | Protocol behavior |
| **Data Format Extensions** | URL encoding, multipart form data | Request formatting |

**VuGen Best Practices:**

```
✅ DO:
- Use meaningful transaction names (Login, Search, Checkout)
- Parameterize all dynamic data (usernames, passwords, search terms)
- Correlate all session IDs and tokens
- Add checkpoints for critical verifications
- Use think times for realism
- Comment your code for maintainability
- Test with single user before load testing
- Use runtime settings appropriate for test type

❌ DON'T:
- Hardcode values that will change
- Ignore correlation warnings
- Use default transaction names (Action_Transaction)
- Record unnecessary steps
- Forget to remove debugging logs for load tests
- Use excessive think times in load tests
- Ignore replay errors
- Mix test data with script logic
```

**VuGen Troubleshooting:**

| Problem | Common Cause | Solution |
|---------|--------------|----------|
| **Script fails on replay** | Missing correlation | Scan for correlations |
| **404 errors** | URL changed or dynamic | Check base URL, parameters |
| **Parameter not replaced** | Parameter name typo | Verify {paramName} syntax |
| **Think time too long** | Runtime setting | Adjust in runtime settings |
| **Checkpoint fails** | Content changed | Update expected text |
| **Replay slow** | Extended logging | Set to standard logging |
| **Memory errors** | Script too large | Split into multiple scripts |

**Beyond Recording: Making Scripts Robust and Maintainable**

After recording, parameterization, and correlation, scripts need additional enhancements for realism, validation, and maintainability.

**1. Adding Transactions**

```c
// Basic transaction
lr_start_transaction("Login");
web_submit_data("login", ...);
lr_end_transaction("Login", LR_AUTO);

// Nested transactions
lr_start_transaction("Checkout");
    lr_start_transaction("AddToCart");
    web_submit_data("addtocart", ...);
    lr_end_transaction("AddToCart", LR_AUTO);

    lr_start_transaction("Payment");
    web_submit_data("payment", ...);
    lr_end_transaction("Payment", LR_AUTO);
lr_end_transaction("Checkout", LR_AUTO);

// Transaction with custom status
if (responseTime > 5000) {
    lr_end_transaction("Search", LR_FAIL);
} else {
    lr_end_transaction("Search", LR_PASS);
}

// Transaction with manual time measurement
time_t start = time(NULL);
// actions...
time_t end = time(NULL);
lr_end_transaction("Custom", LR_AUTO, end - start);
```

**2. Adding Checkpoints**

```c
// Text checkpoint
web_reg_find("Text=Welcome, {username}",
    "Fail=NotFound",
    LAST);

// Image checkpoint
web_image_check("LogoCheck",
    "Src=logo.png",
    LAST);

// Regular expression checkpoint
web_global_verification("Text=error|exception|fail",
    "Fail=Found",
    LAST);

// JSON value verification
web_reg_find_json("QueryString=$.status",
    "ExpectedValue=success",
    LAST);

// Manual checkpoint with lr_checkpoint
if (strstr(lr_eval_string("{response}"), "success") == NULL) {
    lr_error_message("Expected 'success' not found");
    lr_end_transaction("Checkout", LR_FAIL);
}
```

**3. Adding Think Time**

```c
// Fixed think time
lr_think_time(5);  // 5 seconds delay

// Random think time
lr_think_time(rand() % 10 + 5);  // 5-15 seconds

// Conditional think time
if (atoi(lr_eval_string("{IterationNum}")) == 1) {
    lr_think_time(10);  // First iteration longer
} else {
    lr_think_time(3);   // Subsequent iterations shorter
}

// Think time based on transaction
lr_start_transaction("ProductView");
web_url("product", ...);
lr_end_transaction("ProductView", LR_AUTO);

// Longer think time for product viewing
lr_think_time(8);
```

**4. Adding Comments and Documentation**

```c
// Single line comment
// This section handles user login with credentials from CSV

/* Multi-line comment
 * This script simulates an e-commerce user journey:
 * 1. Login with parameterized credentials
 * 2. Search for products
 * 3. View product details
 * 4. Add to cart
 * 5. Checkout and payment
 * 6. Logout
 */

// Runtime parameter documentation
// Users: {username} from users.csv
// Products: {productId} from products.csv
// Search terms: {searchTerm} from searches.csv

// Correlation documentation
// Captures JSESSIONID from login response for session management
web_reg_save_param("JSESSIONID",
    "LB=JSESSIONID=",
    "RB=;",
    LAST);
```

**5. Error Handling**

```c
// Check response code
int rc = web_get_int_property(HTTP_INFO_RETURN_CODE);
if (rc != 200 && rc != 302) {
    lr_error_message("Unexpected response code: %d", rc);
    lr_end_transaction("Login", LR_FAIL);
    return -1;
}

// Retry on failure
int maxRetries = 3;
int retryCount = 0;
int success = 0;

while (!success && retryCount < maxRetries) {
    retryCount++;
    lr_output_message("Attempt %d of %d", retryCount, maxRetries);

    web_url("search", ...);

    if (web_get_int_property(HTTP_INFO_RETURN_CODE) == 200) {
        success = 1;
    } else {
        lr_think_time(2);  // Wait before retry
    }
}

if (!success) {
    lr_error_message("Failed after %d retries", maxRetries);
}

// Graceful degradation
if (web_get_int_property(HTTP_INFO_RETURN_CODE) == 503) {
    lr_output_message("Service unavailable, skipping checkout");
    lr_end_transaction("Checkout", LR_STOP);
    return 0;  // Continue with next iteration
}
```

**6. Runtime Settings Configuration**

```
Run-Time Settings Dialog:

Run Logic Tab:
├── Number of iterations: 10
├── Run until completion: Disabled
├── Run for: 5 minutes
└── Initialize before: Start Vuser

Pacing Tab:
├── As soon as the previous iteration ends
├── After the previous iteration ends: Wait 5 seconds
├── Random: 2-5 seconds
└── Fixed: 10 seconds

Log Tab:
├── Standard log
├── Extended log: Parameter substitution, Data returned by server
├── Send messages only when an error occurs
└── Always send messages

Think Time Tab:
├── Ignore think time (fast)
├── Replay think time as recorded
├── Multiply recorded think time by: 0.5
├── Use random percentage of recorded think time: 50-150%
└── Limit think time to: 30 seconds

General Tab:
├── Run as process
├── Run as thread (recommended)
├── Disable script step debugger
├── Automatically determine transaction status
└── Enable image and text check

Network Tab:
├── Use system proxy settings
├── No proxy
├── Manual proxy: proxy.company.com:8080
└── Browser cache simulation: Enabled

Browser Tab:
├── Simulate browser cache: Enabled
├── Clear cache each iteration: Disabled
├── Check for newer pages: Every visit
└── User-Agent: Internet Explorer 11
```

**7. Conditional Logic**

```c
// If-else based on parameter
if (strcmp(lr_eval_string("{userType}"), "premium") == 0) {
    lr_output_message("Premium user - accessing special offers");
    web_url("premium_offers", ...);
} else {
    lr_output_message("Regular user - standard browsing");
    web_url("regular_offers", ...);
}

// Switch based on multiple options
switch(atoi(lr_eval_string("{action}"))) {
    case 1:
        web_url("search", ...);
        break;
    case 2:
        web_url("product", ...);
        break;
    case 3:
        web_url("cart", ...);
        break;
    default:
        lr_output_message("Unknown action: %s", lr_eval_string("{action}"));
}

// Loop with condition
int maxItems = atoi(lr_eval_string("{productCount}"));
for (i=1; i<=maxItems; i++) {
    lr_param_sprintf("currentProduct", "{productId_%d}", i);
    lr_output_message("Processing product: %s", lr_eval_string("{currentProduct}"));
    web_url("product_detail",
        "URL=https://example.com/product/{currentProduct}",
        LAST);
    lr_think_time(2);
}
```

**8. Script Modularization**

```c
// Include common functions
#include "common_functions.h"

// Define reusable function
int login(char* username, char* password) {
    lr_start_transaction("Login");

    web_submit_data("authenticate",
        "Action=https://example.com/login",
        "Method=POST",
        ITEMDATA,
        "Name=username", "Value={username}", ENDITEM,
        "Name=password", "Value={password}", ENDITEM,
        LAST);

    if (web_get_int_property(HTTP_INFO_RETURN_CODE) == 200) {
        lr_end_transaction("Login", LR_PASS);
        return 0;
    } else {
        lr_end_transaction("Login", LR_FAIL);
        return -1;
    }
}

// Use in script
Action() {
    if (login(lr_eval_string("{username}"), lr_eval_string("{password}")) != 0) {
        lr_exit(LR_EXIT_VUSER, LR_FAIL);
    }

    // Continue with other actions
}
```

**9. Data Generation Functions**

```c
// Generate random email
char email[100];
sprintf(email, "user_%d@test.com", rand() % 10000);
lr_save_string(email, "randomEmail");

// Generate timestamp
lr_save_datetime("%Y-%m-%d_%H-%M-%S", DATE_NOW, "timestamp");

// Generate random string
char randomString[20];
char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
int len = 10;
for (int i = 0; i < len; i++) {
    randomString[i] = charset[rand() % (sizeof(charset)-1)];
}
randomString[len] = '\0';
lr_save_string(randomString, "randomId");

// Generate UUID-like string
lr_param_sprintf("uuid", "%04x%04x-%04x-%04x-%04x-%04x%04x%04x",
    rand() % 65535, rand() % 65535,
    rand() % 65535,
    rand() % 65535,
    rand() % 65535,
    rand() % 65535, rand() % 65535, rand() % 65535);
```

**10. Script Enhancement Checklist**

```
□ Transactions added for all key business steps
□ Checkpoints validate critical responses
□ Think time configured appropriately
□ Comments document script purpose and logic
□ Error handling for expected failures
□ Runtime settings optimized for test type
□ Conditional logic handles variations
□ Modular functions for reusable code
□ Data generation for dynamic content
□ Logging for debugging (disabled in load tests)
□ Proper indentation and formatting
□ Version control comments (author, date, purpose)
```

**Transforming a Linear Recording into an Intelligent Program:**

A recorded script is linear: Step A, then Step B, then Step C. Real-world user behavior is rarely linear. Users may repeat actions, take different paths based on data, or handle unexpected server responses. To simulate this, you need loops and conditional logic.

**Implementing Conditional Logic:**

The `if-else` statement is your primary tool for creating branches in your script.

```c
// Example: Handling different responses after a login attempt
web_reg_save_param("LoginStatus",
    "LB=status": "\"",
    "RB=\"",
    LAST);

web_submit_data("login.php",
    "Action=https://example.com/login",
    ...
    LAST);

// Check the captured status and take different actions
if (strcmp(lr_eval_string("{LoginStatus}"), "success") == 0) {
    lr_output_message("Login successful. Proceeding to dashboard.");
    web_url("dashboard.php", ...);
} else {
    lr_output_message("Login failed. Status: %s", lr_eval_string("{LoginStatus}"));
    // Optionally, attempt login again with different credentials
    // Or fail the transaction
    lr_end_transaction("Login", LR_FAIL);
}
```

**Implementing Loops for Repetitive Actions:**

`for` and `while` loops are essential for simulating iterative behaviors, such as adding multiple items to a cart or browsing through multiple pages of search results.

- **`for` Loop:** Use when you know in advance how many times an action should repeat.

```c
// Example: Adding 5 different items to a shopping cart
int item_count;
char item_param[50];

for (item_count = 1; item_count <= 5; item_count++) {
    // Build the parameter name dynamically, e.g., "item_id_1", "item_id_2"
    sprintf(item_param, "{item_id_%d}", item_count);

    web_submit_data("AddToCart.php",
        "Action=https://example.com/cart/add",
        "Method=POST",
        "RecContentType=text/html",
        "Referer=https://example.com/products",
        "Mode=HTML",
        ITEMDATA,
        "Name=itemId", "Value=", item_param, ENDITEM,
        LAST);

    lr_output_message("Added item %s to cart.", lr_eval_string(item_param));
}
```

- **`while` Loop:** Use when you need to repeat an action until a certain condition is met, such as paging through search results until you find a specific product.

```c
// Example: Paging through search results until the desired product is found
int page = 1;
int found = 0;
char next_page_url[256];

while (found == 0) {
    lr_output_message("Searching page %d...", page);

    web_url("search_results.php",
        "URL=https://example.com/search?page={page}",
        ...
        LAST);

    web_reg_save_param("product_found",
        "LB=Product ID: ",
        "RB= ",
        "Ord=All",
        LAST);

    // Check if the target product is on this page (logic to examine product_found array)
    // ... (omitted for brevity) ...

    if (/* product found */) {
        found = 1;
        lr_output_message("Product found on page %d.", page);
    } else {
        // Check if there is a "Next Page" link
        web_reg_save_param("next_link",
            "LB=<a href=\"",
            "RB=\" class=\"next\">",
            LAST);

        if (strlen(lr_eval_string("{next_link}")) == 0) {
            lr_output_message("No more pages. Product not found.");
            found = -1; // Exit loop, product not found
        } else {
            page++;
            lr_output_message("Going to next page.");
        }
    }
}
```

content.details:
**The Scenario:** An airline booking website. The process is: (1) Search for flights, (2) A list of available flights is returned, (3) User clicks on a specific flight, (4) A seat map is displayed, (5) User selects a preferred seat type (if available).

**The Advanced Scripting Solution:**

```c
Action()
{
    int num_flights, i;
    char flight_id_param[50];
    int seat_selected = 0;

    lr_start_transaction("Flight_Search_and_Select");

    // Step 1: Search for flights (standard recorded steps)
    web_submit_data("flight_search.php",
        "Action=https://example.com/flights/search",
        "Method=POST",
        ITEMDATA,
        "Name=origin", "Value=LAX", ENDITEM,
        "Name=dest", "Value=JFK", ENDITEM,
        "Name=date", "Value=2024-05-20", ENDITEM,
        LAST);

    // Step 2: Capture all available flight IDs from the search results
    web_reg_save_param("flight_id",
        "LB=<input type=\"radio\" name=\"flight\" value=\"",
        "RB=\">",
        "Ord=All",
        "Search=Body",
        LAST);

    web_url("flight_results.php",
        "URL=https://example.com/flights/results",
        ...
        LAST);

    num_flights = atoi(lr_eval_string("{flight_id_count}"));
    lr_output_message("Found %d flights.", num_flights);

    if (num_flights == 0) {
        lr_error_message("No flights found. Aborting.");
        lr_end_transaction("Flight_Search_and_Select", LR_FAIL);
        return -1;
    }

    // Step 3: Loop through flights until we find one with a preferred aisle seat
    for (i = 1; i <= num_flights; i++) {
        sprintf(flight_id_param, "{flight_id_%d}", i);
        lr_save_string(lr_eval_string(flight_id_param), "SelectedFlight");
        lr_output_message("Trying flight: %s", lr_eval_string("{SelectedFlight}"));

        // Step 4: Click on the flight to see seat map
        web_submit_data("select_flight.php",
            "Action=https://example.com/flights/select",
            "Method=POST",
            ITEMDATA,
            "Name=flight", "Value={SelectedFlight}", ENDITEM,
            LAST);

        // Step 5: Check if an aisle seat (seat type 'A') is available
        web_reg_save_param("aisle_seat",
            "LB=seatType=\"A\" seatId=\"",
            "RB=\"",
            "Ord=1", // Just need to know if at least one exists
            LAST);

        web_url("seat_map.php",
            "URL=https://example.com/flights/seatmap?flight={SelectedFlight}",
            ...
            LAST);

        if (strlen(lr_eval_string("{aisle_seat}")) > 0) {
            lr_output_message("Aisle seat found on flight %s!", lr_eval_string("{SelectedFlight}"));
            seat_selected = 1;
            break; // Exit the loop, we have our flight
        } else {
            lr_output_message("No aisle seat on this flight. Trying next.");
        }
    }

    // Step 6: Outcome of the search
    if (seat_selected == 1) {
        // Proceed to book the seat
        web_submit_data("book_seat.php",
            "Action=https://example.com/flights/book",
            "Method=POST",
            ITEMDATA,
            "Name=flight", "Value={SelectedFlight}", ENDITEM,
            "Name=seatId", "Value={aisle_seat}", ENDITEM,
            LAST);
        lr_end_transaction("Flight_Search_and_Select", LR_PASS);
    } else {
        lr_error_message("Could not find a flight with an aisle seat.");
        lr_end_transaction("Flight_Search_and_Select", LR_FAIL);
    }

    return 0;
}
```

