                    returnStdout: true
                ).trim()

                if (p0Failures.toInteger() > 0) {
                    error("Quality Gate failed: ${p0Failures} P0 failures detected")
                }

                def p1Failures = sh(
                    script: "grep -c 'priority=\"P1\".*status=\"FAIL\"' results/output.xml || true",
                    returnStdout: true
                ).trim()

                if (p1Failures.toInteger() > 3) {
                    unstable("Warning: ${p1Failures} P1 failures detected")
                }
            }
        }
    }
}
```

