**Jenkinsfile for Microservices Testing:**

```groovy
pipeline {
    agent none

    environment {
        DOCKER_REGISTRY = 'registry.company.com'
        TEST_ENV = 'staging'
        REPORT_DIR = 'reports'
    }

    stages {
        stage('Build and Deploy Services') {
            parallel {
                stage('Build Service A') {
                    agent { label 'builder' }
                    steps {
                        dir('services/service-a') {
                            sh 'docker build -t ${DOCKER_REGISTRY}/service-a:${BUILD_NUMBER} .'
                            sh 'docker push ${DOCKER_REGISTRY}/service-a:${BUILD_NUMBER}'
                            sh 'kubectl set image deployment/service-a service-a=${DOCKER_REGISTRY}/service-a:${BUILD_NUMBER}'
                        }
                    }
                }
                stage('Build Service B') {
                    agent { label 'builder' }
                    steps {
                        dir('services/service-b') {
                            sh 'docker build -t ${DOCKER_REGISTRY}/service-b:${BUILD_NUMBER} .'
                            sh 'docker push ${DOCKER_REGISTRY}/service-b:${BUILD_NUMBER}'
                            sh 'kubectl set image deployment/service-b service-b=${DOCKER_REGISTRY}/service-b:${BUILD_NUMBER}'
                        }
                    }
                }
                // Additional services...
            }
        }

        stage('Wait for Deployment') {
            agent { label 'builder' }
            steps {
                sh 'kubectl rollout status deployment/service-a'
                sh 'kubectl rollout status deployment/service-b'
                sh 'sleep 10'  # Give services time to warm up
            }
        }

        stage('Test Services') {
            parallel {
                stage('Service A Unit Tests') {
                    agent { label 'test-runner' }
                    steps {
                        sh """
                            robot --outputdir ${REPORT_DIR}/service-a \
                                  --include service-a-unit \
                                  --variable SERVICE_URL:http://service-a:8080 \
                                  tests/service-a/
                        """
                    }
                }
                stage('Service B Unit Tests') {
                    agent { label 'test-runner' }
                    steps {
                        sh """
                            robot --outputdir ${REPORT_DIR}/service-b \
                                  --include service-b-unit \
                                  --variable SERVICE_URL:http://service-b:8080 \
                                  tests/service-b/
                        """
                    }
                }
                stage('Service C Unit Tests') {
                    agent { label 'test-runner' }
                    steps {
                        sh """
                            robot --outputdir ${REPORT_DIR}/service-c \
                                  --include service-c-unit \
                                  --variable SERVICE_URL:http://service-c:8080 \
                                  tests/service-c/
                        """
                    }
                }
            }
        }

        stage('Integration Tests') {
            agent { label 'test-runner' }
            steps {
                sh """
                    robot --outputdir ${REPORT_DIR}/integration \
                          --include integration \
                          --critical P0 \
                          --variable API_GATEWAY:http://api-gateway:8080 \
                          tests/integration/
                """
            }
        }

        stage('End-to-End Tests') {
            agent { label 'test-runner' }
            when { branch 'main' }
            steps {
                sh """
                    robot --outputdir ${REPORT_DIR}/e2e \
                          --include e2e \
                          --critical P0 \
                          --variable APP_URL:https://staging.company.com \
                          tests/e2e/
                """
            }
        }
    }

    post {
        always {
            // Publish all reports
            step([$class: 'RobotPublisher', outputPath: REPORTS_DIR])
            archiveArtifacts artifacts: '${REPORT_DIR}/**/*'

            // Send summary to Slack
            def summary = createSummary()
            slackSend(
                color: currentBuild.result == 'SUCCESS' ? 'good' : 'danger',
                message: "${currentBuild.result}: ${env.JOB_NAME} #${env.BUILD_NUMBER}\n${summary}"
            )
        }

        failure {
            // Trigger rollback
            sh 'kubectl rollout undo deployment/service-a'
            sh 'kubectl rollout undo deployment/service-b'
        }
    }
}

def createSummary() {
    def summary = ""
    def suites = ['service-a', 'service-b', 'service-c', 'integration', 'e2e']
    for (suite in suites) {
        def reportFile = "${REPORT_DIR}/${suite}/output.xml"
        if (fileExists(reportFile)) {
            def passRate = sh(
                script: """
                    python -c "
import xml.etree.ElementTree as ET
tree = ET.parse('${reportFile}')
root = tree.getroot()
total = len(root.findall('.//test'))
passed = len([t for t in root.findall('.//test') if t.find('status').get('status') == 'PASS'])
print(f'{suite}: {passed}/{total} ({(passed/total*100):.1f}%)')
                    "
                """,
                returnStdout: true
            ).trim()
            summary += "${passRate}\n"
        }
    }
    return summary
}
```

questions.answer:
**TestNG's Killer Features:**

TestNG's popularity stems from its comprehensive feature set that addresses real-world testing challenges.

**1. Annotations**

Annotations are the heart of TestNG. They provide fine-grained control over test lifecycle.

```java
public class AnnotationDemo {

    @BeforeSuite
    public void beforeSuite() {
        System.out.println("Runs once before all tests in suite");
    }

    @BeforeTest
    public void beforeTest() {
        System.out.println("Runs before each <test> tag in testng.xml");
    }

    @BeforeClass
    public void beforeClass() {
        System.out.println("Runs once before first test method in this class");
    }

    @BeforeMethod
    public void beforeMethod() {
        System.out.println("Runs before each test method");
    }

    @Test
    public void testMethod1() {
        System.out.println("Test method 1");
    }

    @Test
    public void testMethod2() {
        System.out.println("Test method 2");
    }

    @AfterMethod
    public void afterMethod() {
        System.out.println("Runs after each test method");
    }

    @AfterClass
    public void afterClass() {
        System.out.println("Runs after all test methods in this class");
    }

    @AfterTest
    public void afterTest() {
        System.out.println("Runs after each <test> tag completes");
    }

    @AfterSuite
    public void afterSuite() {
        System.out.println("Runs once after all tests in suite");
    }
}
```

**2. Test Groups**

Groups allow you to categorize tests and run them selectively.

```java
public class GroupDemo {

    @Test(groups = { "smoke", "login" })
    public void testValidLogin() {
        System.out.println("Testing valid login - smoke test");
    }

    @Test(groups = { "regression", "login" })
    public void testInvalidLogin() {
        System.out.println("Testing invalid login - regression");
    }

    @Test(groups = { "smoke", "checkout" })
    public void testAddToCart() {
        System.out.println("Testing add to cart - smoke test");
    }

    @Test(groups = { "regression", "checkout" })
    public void testCheckoutProcess() {
        System.out.println("Testing checkout - regression");
    }

    @Test(groups = { "database", "slow" })
    public void testDatabaseQuery() {
        System.out.println("Testing database - slow test");
    }
}
```

**testng.xml for groups:**
```xml
<!DOCTYPE suite SYSTEM "http://testng.org/testng-1.0.dtd">
<suite name="Group Suite">
    <test name="Smoke Tests">
        <groups>
            <run>
                <include name="smoke"/>
            </run>
        </groups>
        <classes>
            <class name="com.example.GroupDemo"/>
        </classes>
    </test>

    <test name="Regression Tests">
        <groups>
            <run>
                <include name="regression"/>
                <exclude name="slow"/>
            </run>
        </groups>
        <classes>
            <class name="com.example.GroupDemo"/>
        </classes>
    </test>
</suite>
```

**3. Parameterized Testing**

TestNG offers two ways to pass parameters to tests.

**Using @Parameters (from testng.xml):**

```java
public class ParameterDemo {

    @Test
    @Parameters({"browser", "environment"})
    public void testWithParameters(String browser, String environment) {
        System.out.println("Running on " + browser + " in " + environment);
        // Test logic
    }
}
```

**testng.xml:**
```xml
<suite name="Parameter Suite">
    <parameter name="browser" value="chrome"/>
    <parameter name="environment" value="staging"/>

    <test name="Parameter Test">
        <classes>
            <class name="com.example.ParameterDemo"/>
        </classes>
    </test>
</suite>
```

**Using @DataProvider (more powerful):**

```java
public class DataProviderDemo {

    @DataProvider(name = "loginData")
    public Object[][] getLoginData() {
        return new Object[][]{
            {"admin@example.com", "admin123", true},
            {"user@example.com", "user123", true},
            {"invalid@example.com", "wrong", false},
            {"", "", false}
        };
    }

    @Test(dataProvider = "loginData")
    public void testLogin(String username, String password, boolean shouldSucceed) {
        LoginPage loginPage = new LoginPage();
        boolean result = loginPage.login(username, password);

        if (shouldSucceed) {
            Assert.assertTrue(result, "Login should succeed for " + username);
        } else {
            Assert.assertFalse(result, "Login should fail for " + username);
        }
    }

    @DataProvider(name = "excelData")
    public Object[][] getDataFromExcel() throws IOException {
        // Read from Excel file
        return ExcelReader.readData("testdata.xlsx", "Sheet1");
    }

    @DataProvider(name = "databaseData")
    public Object[][] getDataFromDatabase() {
        // Read from database
        return DatabaseReader.getTestData();
    }
}
```

**4. Dependency Testing**

Specify that certain tests depend on others.

```java
public class DependencyDemo {

    @Test
    public void testCreateUser() {
        System.out.println("Creating user");
        // If this fails, dependent tests are skipped
    }

    @Test(dependsOnMethods = {"testCreateUser"})
    public void testLoginWithNewUser() {
        System.out.println("Testing login with created user");
        // Runs only if testCreateUser passes
    }

    @Test(dependsOnMethods = {"testLoginWithNewUser"})
    public void testUpdateUserProfile() {
        System.out.println("Testing profile update");
    }

    @Test(dependsOnGroups = {"smoke"})
    public void testDependsOnGroup() {
        System.out.println("Depends on all smoke tests passing");
    }

    @Test(alwaysRun = true)
    public void testAlwaysRun() {
        System.out.println("This runs even if dependencies fail");
    }
}
```

**5. Parallel Test Execution**

TestNG can run tests in parallel at multiple levels.

```java
public class ParallelDemo {

    @Test(threadPoolSize = 3, invocationCount = 10)
    public void testWithThreadPool() {
        System.out.println("Test running in thread: " + Thread.currentThread().getId());
        // This test runs 10 times with 3 threads in parallel
    }
}
```

**testng.xml for parallel execution:**
```xml
<suite name="Parallel Suite" parallel="tests" thread-count="5">

    <test name="Test 1" parallel="classes" thread-count="2">
        <classes>
            <class name="com.example.TestClass1"/>
            <class name="com.example.TestClass2"/>
        </classes>
    </test>

    <test name="Test 2" parallel="methods" thread-count="3">
        <classes>
            <class name="com.example.TestClass3"/>
        </classes>
    </test>

</suite>
```

**Parallel execution modes:**
- `parallel="methods"`: Run test methods in separate threads
- `parallel="tests"`: Run `<test>` tags in separate threads
- `parallel="classes"`: Run test classes in separate threads
- `parallel="instances"`: Run instances in separate threads

**6. Test Timeouts**

Prevent tests from hanging indefinitely.

```java
public class TimeoutDemo {

    @Test(timeOut = 5000)  // 5 seconds
    public void testWithTimeout() throws InterruptedException {
        // This test will fail if it takes more than 5 seconds
        Thread.sleep(6000);  // This would cause failure
    }

    @Test
    public void testWithoutTimeout() {
        // Could run indefinitely
    }
}
```

**7. Expected Exceptions**

Test that code throws expected exceptions.

```java
public class ExceptionDemo {

    @Test(expectedExceptions = IllegalArgumentException.class,
          expectedExceptionsMessageRegExp = ".*negative.*")
    public void testNegativeAmount() {
        Account account = new Account();
        account.withdraw(-100);  // Should throw IllegalArgumentException
    }

    @Test(expectedExceptions = {IOException.class, SQLException.class})
    public void testMultipleExceptions() throws Exception {
        if (Math.random() > 0.5) {
            throw new IOException();
        } else {
            throw new SQLException();
        }
    }
}
```

**8. Ignoring Tests**

Temporarily disable tests.

```java
public class IgnoreDemo {

    @Test(enabled = false)
    public void testNotReady() {
        // This test won't run
    }

    @Test
    public void testActive() {
        // This test runs normally
    }
}
```

**9. Listeners**

Listeners allow you to add custom behavior to test execution.

```java
public class CustomListener implements ITestListener {

    @Override
    public void onTestStart(ITestResult result) {
        System.out.println("Test started: " + result.getName());
    }

    @Override
    public void onTestSuccess(ITestResult result) {
        System.out.println("Test passed: " + result.getName());
        // Send notification, update dashboard, etc.
    }

    @Override
    public void onTestFailure(ITestResult result) {
        System.out.println("Test failed: " + result.getName());
        // Take screenshot, log error, send alert
        takeScreenshot();
        logFailure(result.getThrowable());
    }

    @Override
    public void onTestSkipped(ITestResult result) {
        System.out.println("Test skipped: " + result.getName());
    }

    private void takeScreenshot() {
        // Implementation
    }

    private void logFailure(Throwable t) {
        // Implementation
    }
}
```

**Using listeners:**
```xml
<suite name="Listener Suite">
    <listeners>
        <listener class-name="com.example.CustomListener"/>
    </listeners>
    <test name="Test with Listener">
        <classes>
            <class name="com.example.MyTest"/>
        </classes>
    </test>
</suite>
```

content.explanation:
**The Complete Guide to TestNG Annotations:**

TestNG provides a rich set of annotations that give you fine-grained control over test execution. Understanding their order and proper usage is key to writing effective tests.

**Annotation Hierarchy and Execution Order:**

```
@BeforeSuite
    ↓
@BeforeTest
    ↓
@BeforeGroups (if groups defined)
    ↓
@BeforeClass
    ↓
@BeforeMethod
    ↓
    @Test Method 1
    ↓
@AfterMethod
    ↓
@BeforeMethod
    ↓
    @Test Method 2
    ↓
@AfterMethod
    ↓
@AfterClass
    ↓
@AfterGroups (if groups defined)
    ↓
@AfterTest
    ↓
@AfterSuite
```

**Detailed Annotation Reference:**

| Annotation | Scope | Purpose | Example |
|------------|-------|---------|---------|
| **@BeforeSuite** | Suite | Runs once before all tests in suite | Initialize global resources, database connections |
| **@AfterSuite** | Suite | Runs once after all tests in suite | Clean up global resources, close connections |
| **@BeforeTest** | `<test>` tag | Runs before each `<test>` in testng.xml | Configure test-specific settings |
| **@AfterTest** | `<test>` tag | Runs after each `<test>` in testng.xml | Clean up test-specific data |
| **@BeforeGroups** | Groups | Runs before first test in specified group | Initialize group-specific resources |
| **@AfterGroups** | Groups | Runs after last test in specified group | Clean up group-specific resources |
| **@BeforeClass** | Class | Runs once before first test method in class | Initialize class-level resources |
| **@AfterClass** | Class | Runs once after all test methods in class | Clean up class-level resources |
| **@BeforeMethod** | Method | Runs before each test method | Set up test data, initialize objects |
| **@AfterMethod** | Method | Runs after each test method | Clean up test data, log results |
| **@Test** | Method | Marks a method as a test method | Actual test logic |

**Advanced Test Annotation Parameters:**

```java
public class AdvancedAnnotationDemo {

    @Test(
        description = "This test verifies user login with valid credentials",
        timeOut = 10000,
        invocationCount = 5,
        invocationTimeOut = 60000,
        threadPoolSize = 3,
        successPercentage = 80,
        enabled = true,
        groups = {"smoke", "login"},
        dependsOnMethods = {"setupDatabase"},
        dependsOnGroups = {"init"},
        alwaysRun = true,
        dataProvider = "loginData",
        dataProviderClass = DataProviders.class,
        expectedExceptions = {SQLException.class},
        expectedExceptionsMessageRegExp = "Connection refused"
    )
    public void complexTest() {
        // Test implementation
    }
}
```

**Annotation Parameters Explained:**

| Parameter | Purpose | Example |
|-----------|---------|---------|
| `description` | Test description for reports | `description = "Verifies login"` |
| `timeOut` | Maximum time in milliseconds | `timeOut = 5000` |
| `invocationCount` | Number of times to run test | `invocationCount = 10` |
| `threadPoolSize` | Threads for parallel execution | `threadPoolSize = 3` |
| `successPercentage` | Minimum success rate | `successPercentage = 90` |
| `enabled` | Whether test runs | `enabled = false` |
| `groups` | Groups this test belongs to | `groups = {"smoke"}` |
| `dependsOnMethods` | Methods this test depends on | `dependsOnMethods = {"setup"}` |
| `dependsOnGroups` | Groups this test depends on | `dependsOnGroups = {"init"}` |
| `alwaysRun` | Run even if dependencies fail | `alwaysRun = true` |
| `dataProvider` | DataProvider method name | `dataProvider = "testData"` |
| `dataProviderClass` | Class containing DataProvider | `dataProviderClass = DataUtils.class` |
| `expectedExceptions` | Exceptions test should throw | `expectedExceptions = {IOException.class}` |

**Practical Example: E-Commerce Test Suite**

```java
public class EcommerceTest {

    private WebDriver driver;
    private TestData testData;

    @BeforeSuite
    public void globalSetup() {
        // Initialize test configuration
        Configuration.load("config.properties");
        Database.initialize();
        System.out.println("Global setup complete");
    }

    @BeforeTest
    public void testSetup() {
        // Configure for specific test type
        testData = new TestData();
        System.out.println("Test-level setup");
    }

    @BeforeGroups("database")
    public void setupDatabaseTests() {
        // Initialize database connection
        Database.connect();
        Database.loadTestData();
    }

    @BeforeClass
    public void classSetup() {
        // Initialize test class resources
        driver = new ChromeDriver();
        driver.manage().window().maximize();
    }

    @BeforeMethod
    public void methodSetup() {
        // Prepare for each test
        driver.get("https://example.com");
        testData.refresh();
    }

    @Test(groups = {"smoke", "login"}, description = "Valid login test")
    public void testValidLogin() {
        LoginPage loginPage = new LoginPage(driver);
        loginPage.login("user@example.com", "password123");
        Assert.assertTrue(loginPage.isLoggedIn());
    }

    @Test(groups = {"regression", "login"}, 
          dataProvider = "invalidLoginData",
          description = "Test invalid login attempts")
    public void testInvalidLogin(String username, String password, String expectedError) {
        LoginPage loginPage = new LoginPage(driver);
        loginPage.login(username, password);
        Assert.assertEquals(loginPage.getErrorMessage(), expectedError);
    }

    @Test(groups = {"smoke", "checkout"}, dependsOnMethods = {"testValidLogin"})
    public void testCheckoutProcess() {
        // Test depends on successful login
        CartPage cart = new CartPage(driver);
        cart.addItem("product-123");
        cart.checkout();
        Assert.assertTrue(cart.isOrderConfirmed());
    }

    @Test(groups = {"database", "slow"}, timeOut = 30000)
    public void testDatabaseQuery() {
        // Test with timeout
        List<User> users = Database.query("SELECT * FROM users");
        Assert.assertTrue(users.size() > 0);
    }

    @DataProvider(name = "invalidLoginData")
    public Object[][] getInvalidLoginData() {
        return new Object[][]{
            {"", "", "Username required"},
            {"user@example.com", "", "Password required"},
            {"", "password123", "Username required"},
            {"wrong@example.com", "wrongpass", "Invalid credentials"}
        };
    }

    @AfterMethod
    public void methodCleanup(ITestResult result) {
        if (!result.isSuccess()) {
            // Take screenshot on failure
            takeScreenshot(result.getName());
        }
        // Clear cookies between tests
        driver.manage().deleteAllCookies();
    }

    @AfterClass
    public void classCleanup() {
        if (driver != null) {
            driver.quit();
        }
    }

    @AfterGroups("database")
    public void cleanupDatabaseTests() {
        Database.cleanTestData();
        Database.disconnect();
    }

    @AfterTest
    public void testCleanup() {
        System.out.println("Test-level cleanup");
    }

    @AfterSuite
    public void globalCleanup() {
        Configuration.cleanup();
        System.out.println("Global cleanup complete");
    }

    private void takeScreenshot(String testName) {
        // Implementation
    }
}
```

**Running Tests Faster with Concurrency:**

One of TestNG's most powerful features is its ability to run tests in parallel, dramatically reducing execution time for large test suites.

**Parallel Execution Levels:**

| Level | Description | Best For | Example |
|-------|-------------|----------|---------|
| **methods** | Run test methods in separate threads | Independent unit tests | `<suite parallel="methods" thread-count="10">` |
| **tests** | Run <test> tags in separate threads | Different test suites | `<suite parallel="tests" thread-count="5">` |
| **classes** | Run test classes in separate threads | Classes with independent tests | `<suite parallel="classes" thread-count="8">` |
| **instances** | Run instances in separate threads | Data-driven tests | `<suite parallel="instances" thread-count="4">` |

**Configuration Examples:**

```xml
<!-- Parallel by methods -->
<suite name="Method Parallel" parallel="methods" thread-count="10">
    <test name="Method Level Parallel">
        <classes>
            <class name="com.example.tests.ParallelTest"/>
        </classes>
    </test>
</suite>

<!-- Parallel by classes -->
<suite name="Class Parallel" parallel="classes" thread-count="5">
    <test name="Class Level Parallel">
        <classes>
            <class name="com.example.tests.TestClass1"/>
            <class name="com.example.tests.TestClass2"/>
            <class name="com.example.tests.TestClass3"/>
        </classes>
    </test>
</suite>

<!-- Parallel by tests -->
<suite name="Test Parallel" parallel="tests" thread-count="3">
    <test name="UI Tests" parallel="methods" thread-count="4">
        <classes>
            <class name="com.example.tests.UITest"/>
        </classes>
    </test>
    <test name="API Tests" parallel="methods" thread-count="4">
        <classes>
            <class name="com.example.tests.APITest"/>
        </classes>
    </test>
    <test name="Database Tests" parallel="methods" thread-count="2">
        <classes>
            <class name="com.example.tests.DatabaseTest"/>
        </classes>
    </test>
</suite>
```

**Thread Pool for Single Test:**

```java
public class ThreadPoolDemo {

    @Test(invocationCount = 10, threadPoolSize = 3)
    public void testWithThreadPool() {
        long threadId = Thread.currentThread().getId();
        System.out.println("Test running in thread: " + threadId);

        // This test will run 10 times across 3 threads
        // Total execution time ~= (single test time * 10) / 3
    }

    @Test(invocationCount = 100, threadPoolSize = 10, timeOut = 10000)
    public void loadTest() {
        // Simulate load test with 100 invocations across 10 threads
        // Each invocation must complete within 10 seconds
        performHeavyOperation();
    }
}
```

**DataProvider Parallelism:**

```java
public class DataProviderParallelDemo {

    @DataProvider(name = "testData", parallel = true)
    public Object[][] getTestData() {
        // This DataProvider will provide data in parallel
        Object[][] data = new Object[100][2];
        for (int i = 0; i < 100; i++) {
            data[i][0] = "user" + i;
            data[i][1] = "pass" + i;
        }
        return data;
    }

    @Test(dataProvider = "testData", threadPoolSize = 5)
    public void testWithParallelData(String username, String password) {
        // This test will run with 5 parallel threads
        // processing data from the DataProvider
        System.out.println(Thread.currentThread().getId() + ": Testing " + username);
        performLogin(username, password);
    }
}
```

**Thread Safety Considerations:**

```java
public class ThreadSafetyDemo {

    // ThreadLocal for thread-safe storage
    private ThreadLocal<WebDriver> driver = new ThreadLocal<>();
    private ThreadLocal<TestData> testData = new ThreadLocal<>();

    @BeforeMethod
    public void setUp() {
        // Each thread gets its own WebDriver instance
        driver.set(new ChromeDriver());
        testData.set(new TestData());
    }

    @Test
    public void test1() {
        WebDriver d = driver.get();  // Thread-safe
        TestData td = testData.get(); // Thread-safe
        d.get("https://example.com");
        td.setValue("key", "value");
    }

    @Test
    public void test2() {
        WebDriver d = driver.get();  // Different instance from test1's thread
        TestData td = testData.get(); // Different instance
        d.get("https://example.com/about");
    }

    @AfterMethod
    public void tearDown() {
        driver.get().quit();
        driver.remove();
        testData.remove();
    }

    // NOT thread-safe - shared state
    private static int counter = 0;

    @Test(invocationCount = 10, threadPoolSize = 3)
    public void notThreadSafe() {
        // This will cause race conditions
        counter++;  // DON'T DO THIS
        System.out.println(counter);  // Values will be unpredictable
    }

    // Thread-safe alternative
    private static AtomicInteger atomicCounter = new AtomicInteger(0);

    @Test(invocationCount = 10, threadPoolSize = 3)
    public void threadSafe() {
        int value = atomicCounter.incrementAndGet();  // Thread-safe
        System.out.println(value);  // Values will be sequential
    }
}
```

**Parallel Execution Best Practices:**

1.  **Make tests independent:** Tests should not share state
2.  **Use ThreadLocal for resources:** WebDriver, database connections
3.  **Avoid static variables:** Unless they're thread-safe
4.  **Set appropriate thread counts:** Consider CPU cores and test nature
5.  **Test thread safety:** Write tests to verify thread safety
6.  **Monitor resource usage:** Don't overload system with too many threads
7.  **Use thread pools wisely:** Match thread count to available resources

**Performance Comparison:**

```
Test Suite: 1000 tests, average 1 second each

Serial execution: 1000 seconds (~16.7 minutes)
Parallel (10 threads): 100 seconds (~1.7 minutes)
Parallel (20 threads): 50 seconds (~0.8 minutes)
Parallel (50 threads): 20 seconds

Savings: 16 minutes → 20 seconds with proper parallelization
```

**Comprehensive Reporting for Test Visibility:**

TestNG automatically generates detailed HTML reports that provide insights into test execution, failures, and trends.

**Default Reports Location:**

After running tests, TestNG creates a `test-output` directory with:

```
test-output/
├── index.html                 # Main report dashboard
├── emailable-report.html      # Email-friendly summary
├── testng-results.xml         # Raw results in XML
├── old/                       # Previous run archives
├── suites/                     # Suite-specific reports
│   ├── SuiteName.html
│   └── SuiteName.xml
├── reports/                    # Test-specific reports
│   └── testsuites.html
└── junitreports/               # JUnit-compatible XML
    └── TEST-com.example.Test.xml
```

**index.html - Main Dashboard:**

The main report provides:
- **Summary**: Total tests, passed, failed, skipped
- **Suite view**: Results organized by suite
- **Test view**: Results by test tag
- **Groups view**: Results by group
- **Reporter output**: Custom log messages
- **Timeline**: Test execution timeline

**Customizing Reports with Listeners:**

```java
public class CustomReportListener implements IReporter {

    @Override
    public void generateReport(List<XmlSuite> xmlSuites, List<ISuite> suites,
                               String outputDirectory) {
        // Create custom report
        try (PrintWriter writer = new PrintWriter("custom-report.html", "UTF-8")) {
            writer.println("<html><head><title>Custom Test Report</title>");
            writer.println("<style>");
            writer.println("body { font-family: Arial; margin: 20px; }");
            writer.println(".pass { color: green; }");
            writer.println(".fail { color: red; }");
            writer.println(".skip { color: orange; }");
            writer.println("table { border-collapse: collapse; width: 100%; }");
            writer.println("th, td { border: 1px solid #ddd; padding: 8px; }");
            writer.println("</style></head><body>");

            writer.println("<h1>Custom Test Report</h1>");

            for (ISuite suite : suites) {
                writer.println("<h2>Suite: " + suite.getName() + "</h2>");

                Map<String, ISuiteResult> results = suite.getResults();
                for (ISuiteResult result : results.values()) {
                    ITestContext context = result.getTestContext();

                    // Summary
                    writer.println("<h3>" + context.getName() + "</h3>");
                    writer.println("<table>");
                    writer.println("<tr><th>Total</th><td>" + 
                        context.getPassedTests().size() +
                        context.getFailedTests().size() +
                        context.getSkippedTests().size() + "</td></tr>");
                    writer.println("<tr><th>Passed</th><td class='pass'>" + 
                        context.getPassedTests().size() + "</td></tr>");
                    writer.println("<tr><th>Failed</th><td class='fail'>" + 
                        context.getFailedTests().size() + "</td></tr>");
                    writer.println("<tr><th>Skipped</th><td class='skip'>" + 
                        context.getSkippedTests().size() + "</td></tr>");
                    writer.println("</table>");

                    // Failed tests details
                    if (context.getFailedTests().size() > 0) {
                        writer.println("<h4>Failed Tests</h4>");
                        writer.println("<table>");
                        writer.println("<tr><th>Test</th><th>Error</th></tr>");

                        for (ITestResult testResult : context.getFailedTests().getAllResults()) {
                            writer.println("<tr>");
                            writer.println("<td>" + testResult.getName() + "</td>");
                            writer.println("<td>" + testResult.getThrowable().getMessage() + "</td>");
                            writer.println("</tr>");
                        }
                        writer.println("</table>");
                    }
                }
            }

            writer.println("</body></html>");
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
```

