import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.core.type.TypeReference;

public class JSONDataProvider {

    @DataProvider(name = "jsonData")
    public static Iterator<Object[]> getJSONData() throws IOException {
        ObjectMapper mapper = new ObjectMapper();

        List<TestData> testDataList = mapper.readValue(
            new File("src/test/resources/testdata.json"),
            new TypeReference<List<TestData>>() {}
        );

        List<Object[]> data = new ArrayList<>();
        for (TestData td : testDataList) {
            data.add(new Object[]{td});
        }

        return data.iterator();
