public class DynamicDataProvider {

    @DataProvider(name = "dynamicData")
    public static Iterator<Object[]> getDynamicData() {
        List<Object[]> data = new ArrayList<>();
        Random random = new Random();

        // Generate 50 random test cases
        for (int i = 0; i < 50; i++) {
            String username = "user" + random.nextInt(1000) + "@test.com";
            String password = generateRandomPassword();
            boolean expected = random.nextBoolean();
            String errorMessage = expected ? null : "Random error";

            TestData td = new TestData(username, password, expected, errorMessage);
            data.add(new Object[]{td});
        }

        return data.iterator();
    }

    private static String generateRandomPassword() {
        String chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
        StringBuilder sb = new StringBuilder();
        Random random = new Random();

        for (int i = 0; i < 10; i++) {
            sb.append(chars.charAt(random.nextInt(chars.length())));
        }

        return sb.toString();
    }
}
