**8. Environment-Specific Data**

```java
public class EnvironmentAwareDataProvider {

    @DataProvider(name = "envData")
    public static Iterator<Object[]> getEnvironmentData(ITestContext context) {
        String environment = context.getCurrentXmlTest()
            .getParameter("environment", "staging");

        if ("production".equals(environment)) {
            return getProductionData();
        } else if ("staging".equals(environment)) {
            return getStagingData();
        } else {
            return getDevData();
        }
    }

    private static Iterator<Object[]> getProductionData() {
        List<Object[]> data = new ArrayList<>();
        // Production-safe test data
        data.add(new Object[]{new TestData("prod-user", "prod-pass", true, null)});
        return data.iterator();
    }

    private static Iterator<Object[]> getStagingData() {
        List<Object[]> data = new ArrayList<>();
        // Staging test data (more comprehensive)
        data.add(new Object[]{new TestData("staging-user1", "pass1", true, null)});
        data.add(new Object[]{new TestData("staging-user2", "pass2", true, null)});
        return data.iterator();
    }

