**Mastering Essential Assertions:**

TestNG provides a comprehensive set of assertion methods. Here's a deep dive into each category with practical examples.

**1. assertEquals and assertNotEquals**

The most frequently used assertions for comparing values.

```java
public class EqualityAssertionsTest {

    @Test
    public void testEquality() {
        // Primitive types
        int actual = 5 + 3;
        Assert.assertEquals(actual, 8, "5 + 3 should equal 8");

        // Strings
        String actualString = "Hello World".toUpperCase();
        Assert.assertEquals(actualString, "HELLO WORLD", 
            "String should be uppercase");

        // With delta for floating point
        double pi = 22.0 / 7.0;
        Assert.assertEquals(pi, 3.142857, 0.001, 
            "Pi approximation should be close");

        // Objects (requires proper equals() implementation)
        User user1 = new User("john@test.com");
        User user2 = new User("john@test.com");
        Assert.assertEquals(user1, user2, 
            "Users with same email should be equal");

        // Not equal
        Assert.assertNotEquals(5, 10, "5 and 10 should not be equal");
    }

    @Test
    public void testMultipleDataTypes() {
        // Boolean
        Assert.assertEquals(true, 5 > 3);

        // Char
        Assert.assertEquals('A', 65); // ASCII comparison

        // Long
        Assert.assertEquals(1000000L, 1000L * 1000L);

        // Byte
        byte b1 = 127;
        byte b2 = 127;
        Assert.assertEquals(b1, b2);
    }
}
```

**2. assertTrue and assertFalse**

For verifying boolean conditions.

```java
public class BooleanAssertionsTest {

    @Test
    public void testBooleanConditions() {
        // Simple condition
        int age = 25;
        Assert.assertTrue(age >= 18, "User should be adult");
        Assert.assertFalse(age < 13, "User should not be a child");

        // Method calls
        List<String> list = Arrays.asList("a", "b", "c");
        Assert.assertTrue(list.contains("b"), 
            "List should contain 'b'");

        // Complex conditions
        User user = new User("john@test.com", "John", 30);
        Assert.assertTrue(
            user.isActive() && user.hasVerifiedEmail(),
            "User should be active and verified"
        );

        // String checks
        String text = "Hello World";
        Assert.assertTrue(text.startsWith("Hello"), 
            "Text should start with Hello");
        Assert.assertFalse(text.contains("Goodbye"), 
            "Text should not contain Goodbye");
    }

    @Test
    public void testWithLambda() {
        // Using lambda for complex validation
        List<Integer> numbers = Arrays.asList(1, 2, 3, 4, 5);

        Assert.assertTrue(
            numbers.stream().allMatch(n -> n > 0),
            "All numbers should be positive"
        );
    }
}
```

**3. assertNull and assertNotNull**

For verifying null/non-null values.

```java
public class NullAssertionsTest {

    private UserService userService = new UserService();

    @Test
    public void testNullChecks() {
        // Verify object exists
        User user = userService.findUserById(123);
        Assert.assertNotNull(user, 
            "User with ID 123 should exist");

        // Verify optional field is null
        Assert.assertNull(user.getMiddleName(), 
            "Middle name should be null for this user");

        // Verify error cases
        User nonExistentUser = userService.findUserById(99999);
        Assert.assertNull(nonExistentUser, 
            "Non-existent user should return null");

        // Chain assertions
        Assert.assertNotNull(user.getEmail(), 
            "Email should not be null");
        Assert.assertNotNull(user.getCreatedDate(), 
            "Created date should not be null");
    }

    @Test
    public void testNullWithCollections() {
        List<User> users = userService.getAllUsers();

        // Collection itself shouldn't be null
        Assert.assertNotNull(users, 
            "User list should not be null");

        // But could be empty
        if (!users.isEmpty()) {
            Assert.assertNotNull(users.get(0).getId(),
                "First user should have ID");
        }
    }
}
```

**4. assertSame and assertNotSame**

For verifying object identity (reference equality).

```java
public class IdentityAssertionsTest {

    @Test
    public void testObjectIdentity() {
        String str1 = "hello";
        String str2 = "hello";
        String str3 = new String("hello");

        // String interning - same reference
        Assert.assertSame(str1, str2, 
            "String literals should share reference");

        // New String creates new object
        Assert.assertNotSame(str1, str3, 
            "new String() creates new object");

        // But they are equal in value
        Assert.assertEquals(str1, str3, 
            "Values should be equal");

        // Custom objects
        User user1 = new User("john@test.com");
        User user2 = user1;  // Same reference
        User user3 = new User("john@test.com");  // Different object

        Assert.assertSame(user1, user2, 
            "Should be same reference");
        Assert.assertNotSame(user1, user3, 
            "Different objects even if equal values");
    }

    @Test
    public void testSingletonPattern() {
        DatabaseConnection conn1 = DatabaseConnection.getInstance();
        DatabaseConnection conn2 = DatabaseConnection.getInstance();

        // Singleton should return same instance
        Assert.assertSame(conn1, conn2, 
            "Singleton should return same instance");
    }
}
```

**5. fail Method**

For explicitly failing a test.

```java
public class FailAssertionsTest {

    @Test
    public void testFailWhenConditionNotMet() {
        boolean condition = checkSomeCondition();

        if (!condition) {
            Assert.fail("Condition not met - test cannot proceed");
        }

        // Continue with test if condition met
    }

    @Test
    public void testExceptionHandling() {
        try {
            riskyOperation();
            // If we get here, no exception was thrown
            Assert.fail("Expected exception was not thrown");
        } catch (ExpectedException e) {
            // Expected, test passes
            Assert.assertTrue(e.getMessage().contains("specific error"));
        }
    }

    @Test(expectedExceptions = IOException.class)
    public void testExpectedException() {
        // Alternative: use expectedExceptions annotation
        throw new IOException();
    }

    @Test
    public void testNotImplemented() {
        // Mark test as not implemented yet
        Assert.fail("Test not implemented yet");
    }
}
```

**6. Asserting Arrays**

```java
public class ArrayAssertionsTest {

    @Test
    public void testArrayEquality() {
        int[] expected = {1, 2, 3, 4, 5};
        int[] actual = {1, 2, 3, 4, 5};

        // Compare arrays by content
        Assert.assertEquals(actual, expected, 
            "Arrays should have same content");

        // Different arrays
        int[] different = {1, 2, 3, 4, 6};
        Assert.assertNotEquals(actual, different);

        // Multi-dimensional arrays
        int[][] expected2D = {{1, 2}, {3, 4}};
        int[][] actual2D = {{1, 2}, {3, 4}};
        Assert.assertEquals(actual2D, expected2D);
    }

    @Test
    public void testArrayConditions() {
        int[] numbers = {1, 2, 3, 4, 5};

        // Check array length
        Assert.assertEquals(numbers.length, 5, 
            "Array should have 5 elements");

        // Check specific element
        Assert.assertEquals(numbers[2], 3, 
            "Third element should be 3");

        // Partial array comparison
        int[] firstThree = Arrays.copyOf(numbers, 3);
        int[] expectedFirstThree = {1, 2, 3};
