        actual.put("b", 2);
        actual.put("a", 1);

        // Maps are equal regardless of iteration order
        Assert.assertEquals(actual, expected, 
            "Maps should be equal");

        // Check specific entry
        Assert.assertEquals(actual.get("a"), 1);
    }

