**5. Environment-Aware Test Selection:**

```xml
<suite name="Environment-Aware Suite">
    <parameter name="environment" value="${env}"/>

    <test name="Environment Tests">
        <method-selectors>
            <method-selector>
                <script language="beanshell">
                    <![CDATA[
                        String env = System.getProperty("environment", "dev");

                        // Get test annotations
                        org.testng.annotations.ITestAnnotation test = 
                            testngMethod.getConstructorOrMethod().getMethod()
                                .getAnnotation(org.testng.annotations.Test.class);

                        if (test != null) {
                            String[] groups = test.groups();
                            for (String group : groups) {
                                // Skip tests marked as "prod-only" in non-prod
                                if (group.equals("prod-only") && !env.equals("production")) {
                                    return false;
                                }
                                // Skip tests marked as "dev-only" in prod
                                if (group.equals("dev-only") && env.equals("production")) {
                                    return false;
                                }
                            }
                        }
                        return true;
                    ]]>
                </script>
            </method-selector>
        </method-selectors>

        <packages>
            <package name="com.example.tests.*"/>
        </packages>
    </test>
</suite>
```

**6. Skipping Tests with Annotations:**

```java
public class ConditionalSkipTest {

    @Test(enabled = false)  // Simple disable
    public void testNotReady() { }

    @Test
    @SkipIf(condition = "${environment == 'production'}")
    public void testSkipInProduction() { }

    @Test
    @SkipIf(condition = "${browser == 'safari'}")
    public void testSkipInSafari() { }
}

// Custom annotation
@Retention(RetentionPolicy.RUNTIME)
@Target({ElementType.METHOD, ElementType.TYPE})
public @interface SkipIf {
    String condition();
}

// Listener to process custom annotation
public class SkipIfListener implements IMethodInterceptor {
    @Override
    public List<IMethodInstance> intercept(List<IMethodInstance> methods, 
                                            ITestContext context) {
        List<IMethodInstance> result = new ArrayList<>();

        for (IMethodInstance method : methods) {
            SkipIf skipIf = method.getMethod().getConstructorOrMethod().getMethod()
                .getAnnotation(SkipIf.class);

            if (skipIf != null) {
                String condition = skipIf.condition();
                // Evaluate condition using expression language
                if (evaluateCondition(condition)) {
                    System.out.println("Skipping " + method.getMethod().getMethodName() + 
                        " because condition: " + condition);
                    continue;  // Skip this method
                }
            }
            result.add(method);
        }
        return result;
    }

    private boolean evaluateCondition(String condition) {
        // Implementation to evaluate condition
        return false;
    }
}
