```java
// BaseTest.java - Base class with thread-safe WebDriver management
public class BaseTest {

    // ThreadLocal for thread-safe WebDriver instances
    protected static ThreadLocal<WebDriver> threadLocalDriver = new ThreadLocal<>();
    protected static ThreadLocal<TestData> threadLocalTestData = new ThreadLocal<>();

    @BeforeMethod
    public void setUp() {
        // Each thread gets its own WebDriver
        WebDriver driver = new ChromeDriver();
        threadLocalDriver.set(driver);

        TestData testData = new TestData();
        threadLocalTestData.set(testData);

        System.out.println("Setup in thread: " + Thread.currentThread().getId());
    }

    protected WebDriver getDriver() {
        return threadLocalDriver.get();
    }

    protected TestData getTestData() {
        return threadLocalTestData.get();
    }

    @AfterMethod
    public void tearDown() {
        WebDriver driver = threadLocalDriver.get();
        if (driver != null) {
            driver.quit();
            threadLocalDriver.remove();
        }
        threadLocalTestData.remove();
    }
}

