import org.testng.*;
import java.util.*;

public class SuiteExecutionListener implements ISuiteListener {

    private long suiteStartTime;
    private Map<String, Long> testStartTimes = new HashMap<>();

    @Override
    public void onStart(ISuite suite) {
        suiteStartTime = System.currentTimeMillis();

        System.out.println("\n");
        System.out.println("═══════════════════════════════════════════════════════════════════");
        System.out.println("🚀 SUITE STARTED: " + suite.getName());
        System.out.println("Start time: " + new Date());
        System.out.println("Parallel mode: " + suite.getParallel());
        System.out.println("Thread count: " + suite.getXmlSuite().getThreadCount());

        // Log suite parameters
        Map<String, String> params = suite.getXmlSuite().getParameters();
        if (!params.isEmpty()) {
            System.out.println("Parameters:");
            for (Map.Entry<String, String> entry : params.entrySet()) {
                System.out.println("  " + entry.getKey() + " = " + entry.getValue());
            }
        }
        System.out.println("═══════════════════════════════════════════════════════════════════");
    }

    @Override
    public void onFinish(ISuite suite) {
        long suiteDuration = System.currentTimeMillis() - suiteStartTime;

        System.out.println("\n");
        System.out.println("═══════════════════════════════════════════════════════════════════");
        System.out.println("🏁 SUITE FINISHED: " + suite.getName());
        System.out.println("End time: " + new Date());
        System.out.println("Total duration: " + formatDuration(suiteDuration));

        // Get test results from all tests in suite
        Map<String, ISuiteResult> results = suite.getResults();
        int totalTests = 0;
        int passedTests = 0;
        int failedTests = 0;
        int skippedTests = 0;

        for (ISuiteResult result : results.values()) {
            ITestContext context = result.getTestContext();
            totalTests += context.getAllTestMethods().length;
            passedTests += context.getPassedTests().size();
            failedTests += context.getFailedTests().size();
            skippedTests += context.getSkippedTests().size();
        }

        System.out.println("\nSuite Summary:");
        System.out.println("  Total tests: " + totalTests);
        System.out.println("  Passed: " + passedTests);
        System.out.println("  Failed: " + failedTests);
        System.out.println("  Skipped: " + skippedTests);

        double passRate = totalTests > 0 ? (passedTests * 100.0 / totalTests) : 0;
        System.out.printf("  Pass rate: %.2f%%%n", passRate);
        System.out.println("═══════════════════════════════════════════════════════════════════");
    }

    private String formatDuration(long millis) {
        long seconds = millis / 1000;
        long minutes = seconds / 60;
        long hours = minutes / 60;

        if (hours > 0) {
            return String.format("%d h %d m %d s", hours, minutes % 60, seconds % 60);
        } else if (minutes > 0) {
            return String.format("%d m %d s", minutes, seconds % 60);
        } else {
            return String.format("%d s", seconds);
        }
    }
}
