import org.testng.*;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.stream.Collectors;

public class PerformanceListener implements ITestListener {

    private Map<String, List<Long>> methodExecutionTimes = new ConcurrentHashMap<>();
    private Map<String, Long> methodStartTimes = new ConcurrentHashMap<>();

    @Override
    public void onTestStart(ITestResult result) {
        String key = getMethodKey(result);
        methodStartTimes.put(key, System.nanoTime());
    }

    @Override
    public void onTestSuccess(ITestResult result) {
        recordExecutionTime(result);
    }

    @Override
    public void onTestFailure(ITestResult result) {
        recordExecutionTime(result);
    }

    private void recordExecutionTime(ITestResult result) {
        String key = getMethodKey(result);
        Long startTime = methodStartTimes.remove(key);

        if (startTime != null) {
            long duration = System.nanoTime() - startTime;
            long durationMs = duration / 1_000_000;

            methodExecutionTimes.computeIfAbsent(key, k -> new ArrayList<>())
                .add(durationMs);

            // Log if test is slow
            if (durationMs > 5000) {
                System.out.println("🐢 Slow test detected: " + key + 
                    " took " + durationMs + " ms");
            }
        }
    }

    private String getMethodKey(ITestResult result) {
        return result.getTestClass().getName() + "." + result.getName();
    }

    @Override
    public void onFinish(ITestContext context) {
        generatePerformanceReport();
    }

    private void generatePerformanceReport() {
        System.out.println("\n");
        System.out.println("═══════════════════════════════════════════════════════════════════");
        System.out.println("📊 PERFORMANCE REPORT");
        System.out.println("═══════════════════════════════════════════════════════════════════");

        // Calculate statistics
        List<Map.Entry<String, List<Long>>> sortedMethods = methodExecutionTimes.entrySet()
            .stream()
            .sorted((e1, e2) -> {
                double avg1 = e1.getValue().stream().mapToLong(Long::longValue).average().orElse(0);
                double avg2 = e2.getValue().stream().mapToLong(Long::longValue).average().orElse(0);
                return Double.compare(avg2, avg1);
            })
            .collect(Collectors.toList());

        System.out.printf("%-50s %10s %10s %10s %10s%n", 
            "Method", "Count", "Min(ms)", "Max(ms)", "Avg(ms)");
        System.out.println("--------------------------------------------------------------------------------");

        for (Map.Entry<String, List<Long>> entry : sortedMethods) {
            List<Long> times = entry.getValue();
            LongSummaryStatistics stats = times.stream()
                .mapToLong(Long::longValue)
                .summaryStatistics();

            System.out.printf("%-50s %10d %10d %10d %10.0f%n",
                truncate(entry.getKey(), 50),
                stats.getCount(),
                stats.getMin(),
                stats.getMax(),
                stats.getAverage());
        }

        System.out.println("═══════════════════════════════════════════════════════════════════");
    }

    private String truncate(String str, int length) {
        if (str.length() <= length) return str;
        return str.substring(0, length - 3) + "...";
    }
}
