**JSON Reporter Example:**

```java
public class JSONReporter implements IReporter {

    @Override
    public void generateReport(List<XmlSuite> xmlSuites, List<ISuite> suites,
                               String outputDirectory) {

        JSONObject report = new JSONObject();
        JSONArray suitesArray = new JSONArray();

        for (ISuite suite : suites) {
            JSONObject suiteObj = new JSONObject();
            suiteObj.put("name", suite.getName());

            JSONArray testsArray = new JSONArray();

            Map<String, ISuiteResult> results = suite.getResults();
            for (ISuiteResult result : results.values()) {
                ITestContext context = result.getTestContext();
                JSONObject testObj = new JSONObject();
                testObj.put("name", context.getName());

                // Add test results
                JSONArray passed = new JSONArray();
                for (ITestResult tr : context.getPassedTests().getAllResults()) {
                    passed.put(createTestResultObject(tr));
                }
                testObj.put("passed", passed);

                JSONArray failed = new JSONArray();
                for (ITestResult tr : context.getFailedTests().getAllResults()) {
                    failed.put(createTestResultObject(tr));
                }
                testObj.put("failed", failed);

                JSONArray skipped = new JSONArray();
                for (ITestResult tr : context.getSkippedTests().getAllResults()) {
                    skipped.put(createTestResultObject(tr));
                }
                testObj.put("skipped", skipped);

                testsArray.put(testObj);
            }

            suiteObj.put("tests", testsArray);
            suitesArray.put(suiteObj);
        }

        report.put("suites", suitesArray);

        try (FileWriter file = new FileWriter(outputDirectory + "/test-results.json")) {
            file.write(report.toString(2));
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    private JSONObject createTestResultObject(ITestResult result) {
        JSONObject obj = new JSONObject();
        obj.put("name", result.getName());
        obj.put("className", result.getTestClass().getName());
        obj.put("startTime", result.getStartMillis());
        obj.put("endTime", result.getEndMillis());
        obj.put("duration", result.getEndMillis() - result.getStartMillis());

        if (result.getThrowable() != null) {
            obj.put("error", result.getThrowable().getMessage());
        }

        return obj;
    }
}
