                    writer.println("| Status | Count |");
                    writer.println("|--------|-------|");
                    writer.println("| Total | " + context.getAllTestMethods().length + " |");
                    writer.println("| Passed | " + context.getPassedTests().size() + " |");
                    writer.println("| Failed | " + context.getFailedTests().size() + " |");
                    writer.println("| Skipped | " + context.getSkippedTests().size() + " |");
                    writer.println();

                    // Failed tests details
                    if (!context.getFailedTests().isEmpty()) {
                        writer.println("#### Failed Tests\n");
                        writer.println("| Test | Error | Duration |");
                        writer.println("|------|-------|----------|");

                        for (ITestResult tr : context.getFailedTests().getAllResults()) {
                            writer.printf("| %s | %s | %d ms |%n",
                                tr.getName(),
                                tr.getThrowable().getMessage(),
                                tr.getEndMillis() - tr.getStartMillis());
                        }
                        writer.println();
                    }
                }
            }

        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}
```

