**ExtentReports Listener:**

```java
import com.aventstack.extentreports.*;
import com.aventstack.extentreports.reporter.ExtentSparkReporter;
import com.aventstack.extentreports.reporter.configuration.Theme;
import org.testng.*;
import java.util.*;

public class ExtentReportListener implements ITestListener, ISuiteListener {

    private static ExtentReports extent;
    private static ThreadLocal<ExtentTest> test = new ThreadLocal<>();
    private static ThreadLocal<ITestResult> testResult = new ThreadLocal<>();

    @Override
    public void onStart(ISuite suite) {
        // Initialize ExtentReports
        String reportPath = "test-output/ExtentReport/" + 
            suite.getName() + "_" + new Date().getTime() + ".html";

        ExtentSparkReporter sparkReporter = new ExtentSparkReporter(reportPath);
        sparkReporter.config().setDocumentTitle("Test Automation Report");
        sparkReporter.config().setReportName(suite.getName());
        sparkReporter.config().setTheme(Theme.STANDARD);
        sparkReporter.config().setTimeStampFormat("yyyy-MM-dd HH:mm:ss");

        extent = new ExtentReports();
        extent.attachReporter(sparkReporter);

        // Add system information
        extent.setSystemInfo("OS", System.getProperty("os.name"));
        extent.setSystemInfo("Java Version", System.getProperty("java.version"));
        extent.setSystemInfo("User", System.getProperty("user.name"));

        // Add suite parameters
        Map<String, String> params = suite.getXmlSuite().getParameters();
        for (Map.Entry<String, String> entry : params.entrySet()) {
            extent.setSystemInfo(entry.getKey(), entry.getValue());
        }
    }

    @Override
    public void onTestStart(ITestResult result) {
        ExtentTest extentTest = extent.createTest(
            result.getMethod().getDescription() != null ? 
                result.getMethod().getDescription() : result.getName(),
            result.getMethod().getDescription()
        );

        // Add groups as categories
        String[] groups = result.getMethod().getGroups();
        for (String group : groups) {
            extentTest.assignCategory(group);
        }

        // Add parameters
        Object[] params = result.getParameters();
        if (params != null && params.length > 0) {
            extentTest.info("Parameters: " + Arrays.toString(params));
        }

        test.set(extentTest);
        testResult.set(result);
    }

    @Override
    public void onTestSuccess(ITestResult result) {
        test.get().pass("Test passed successfully");
        logExecutionTime(result);
    }

    @Override
    public void onTestFailure(ITestResult result) {
        test.get().fail(result.getThrowable());
        logExecutionTime(result);

        // Add screenshot if available
        String screenshotPath = getScreenshotPath(result);
        if (screenshotPath != null) {
            try {
                test.get().addScreenCaptureFromPath(screenshotPath);
            } catch (Exception e) {
                test.get().warning("Could not attach screenshot: " + e.getMessage());
            }
        }
    }

    @Override
    public void onTestSkipped(ITestResult result) {
        test.get().skip("Test skipped");
        if (result.getThrowable() != null) {
            test.get().skip(result.getThrowable());
        }
    }

    private void logExecutionTime(ITestResult result) {
        long duration = result.getEndMillis() - result.getStartMillis();
        test.get().info("Execution time: " + duration + " ms");

        if (duration > 5000) {
            test.get().warning("Test took longer than 5 seconds");
        }
    }

    private String getScreenshotPath(ITestResult result) {
        // Implementation to get screenshot path
        // Could be stored in result attributes
        Object screenshot = result.getAttribute("screenshotPath");
        return screenshot != null ? screenshot.toString() : null;
    }

    @Override
    public void onFinish(ISuite suite) {
        extent.flush();
    }

    @Override
    public void onStart(ITestContext context) {}

    @Override
    public void onFinish(ITestContext context) {}

    @Override
    public void onTestFailedButWithinSuccessPercentage(ITestResult result) {}
}
```

