```

**Pipeline Stage Strategy:**

```yaml
# Pipeline stages with appropriate test groups
stages:
  - build
  - fast-tests    # unit, fast (runs on every commit)
  - critical-tests # critical, smoke (runs on merge)
  - full-tests     # regression, integration (nightly)
  - deploy
```

**2. Handling Flaky Tests**

```java
// Retry analyzer for flaky tests
public class FlakyRetryAnalyzer implements IRetryAnalyzer {
    private int retryCount = 0;
    private static final int MAX_RETRY = 2;

    @Override
    public boolean retry(ITestResult result) {
        if (retryCount < MAX_RETRY) {
            retryCount++;
            System.out.println("Retrying test: " + result.getName());
            return true;
        }
        return false;
    }
}

// Mark flaky tests with annotation and retry
@Test(groups = {"flaky"}, retryAnalyzer = FlakyRetryAnalyzer.class)
public void testFlakyOperation() {
    // Flaky test logic
}
